window.AP_ENVIRONMENTAL_SCIENCE_DECKS = [{"id":"apes-unit-12","name":"AP Environmental Science - Unit 1-2","shortName":"Unit 1-2: The Living World","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u12-c1","front":"Abiotic factors","back":"The nonliving physical and chemical components of an ecosystem, including sunlight, temperature, water, air, soil, and nutrients.","sourcePage":1},{"id":"apes-u12-c2","front":"Biotic factors","back":"The living components of an ecosystem, including organisms and their interactions with one another.","sourcePage":1},{"id":"apes-u12-c3","front":"Population","back":"A group of individuals of the same species living in the same area at the same time and capable of interacting and reproducing.","sourcePage":1},{"id":"apes-u12-c4","front":"Community","back":"Populations of different species that occupy the same geographic area Every species occupies a habitat and has an ecological niche","sourcePage":1},{"id":"apes-u12-c5","front":"Habitat","back":"The area or environment where an organism lives, or where an ecological community occurs","sourcePage":1},{"id":"apes-u12-c6","front":"Ecological Niche","back":"The role and position a species has in its environment Includes how a species uses biotic and abiotic resources in its environment, where the species lives, and what it eats","sourcePage":1},{"id":"apes-u12-c7","front":"Competition","back":"Occurs when two individuals are competing for resources in the environment","sourcePage":1},{"id":"apes-u12-c8","front":"Resource Partitioning","back":"Occurs when species can coexist and share resources without any conflict","sourcePage":1},{"id":"apes-u12-c9","front":"Predation","back":"Occurs when one species feeds on another Drives changes in population size Eg Cat & Mouse Polar Bear & Seals Lions & Wildebeests Great White Shark & Elephant Seals","sourcePage":1},{"id":"apes-u12-c10","front":"Symbiotic Relationships","back":"Close, prolonged associations between two or more different organisms of different species","sourcePage":1},{"id":"apes-u12-c11","front":"Mutualism","back":"Both organisms receive beneficial properties from their relationship Eg: pollinators benefit from feeding on plant nectar, and plants benefit from pollinators moving their pollen from plant to plant","sourcePage":2},{"id":"apes-u12-c12","front":"Commensalism","back":"One organism benefits in the relationship and the other are neither harmed nor benefited Eg: Barnacles are sedentary crustaceans that sweep the surrounding water for small, free-floating rganisms. They often grow attached to scallop shells, which has almost no effect on the scallop","sourcePage":2},{"id":"apes-u12-c13","front":"Parasitism","back":"One organism benefits by harming the other organism Eg: Mistletoe is a flowering plant that grows attached to, and within, the vascular system of a tree r shrub. This helps the mistletoe but harms the tree","sourcePage":2},{"id":"apes-u12-c14","front":"Ecotones","back":"Transitional zones where two ecosystems or biomes meet; they often contain species from both communities and may have high biodiversity.","sourcePage":2},{"id":"apes-u12-c15","front":"Ecozones/Ecoregions","back":"Small regions within ecosystems that have similar physical features","sourcePage":2},{"id":"apes-u12-c16","front":"Edge Effects","back":"Ecotones have a great amount of species diversity and biological density Some species only live on the edge of certain habitats","sourcePage":2},{"id":"apes-u12-c17","front":"Bioenergetics","back":"The study of how energy flows through living organisms All energy on Earth comes from the Sun Photosynthetic organisms use solar energy to turn CO and H O into 2 2 carbohydrates Also releases O 2 Biological macromolecules store energy in their chemical bonds Cells use respiration to transfer energy from the chemical bonds of macromolecules to the chemical bonds of smaller molecules like ATP, GTP, NADH, NADPH and FADH 2 This releases CO and H O 2 2 These small, high-energy molecules power all the reactions and processes the cell needs to perform","sourcePage":2},{"id":"apes-u12-c18","front":"Photosynthesis","back":"Plants and algae are producers and perform photosynthesis: they convert solar energy into chemical energy In plants, most photosynthesis occurs in leaves Algae include some bacteria and plant-like protists","sourcePage":3},{"id":"apes-u12-c19","front":"Light-Dependent Reactions","back":"Purpose Convert light energy to chemical energy Reactant(s) = Sunlight + H O 2 Products(s) = O + ATP + NADPH 2","sourcePage":3},{"id":"apes-u12-c20","front":"Light-Independent Reactions","back":"Purpose Use ATP and NADPH to build organic molecules from CO 2 Reactant(s) = CO + ATP + NADPH 2 Product(s) = C H O 6 12 6","sourcePage":3},{"id":"apes-u12-c21","front":"Cellular Respiration","back":"All living organisms require a source of energy, and all living rganisms use the same metabolic pathways to power life Cell respiration is a series of redox reactions. Glucose is oxidized to CO , and this powers the synthesis of ATP, an energy source 2 All living organisms perform cellular respiration","sourcePage":3},{"id":"apes-u12-c22","front":"Autotrophs","back":"Autotrophs produce complex organic compounds from simple substances in the environment Most autotrophs use energy from light (photoautotrophs) Some autotrophs use inorganic chemical reactions instead Autotrophs serve as primary producers in a food chain Example Producers Saprotrophs","sourcePage":3},{"id":"apes-u12-c23","front":"Heterotrophs","back":"Heterotrophs consume other organisms in a food chain A heterotroph is unable to produce organic substances from inorganic ones Heterotrophs depend either directly or indirectly on autotrophs for nutrients and food energy Example Primary Consumers Secondary Consumers Tertiary Consumers Decomposers Detritivores","sourcePage":3},{"id":"apes-u12-c24","front":"Food Chain","back":"shows how energy flow step by step from producer to consumers Eg. Rice→Humans→Microorganisms Corn plants→Beef cattle→Humans Phytoplankton→Crustaceans→Fish→Humans","sourcePage":4},{"id":"apes-u12-c25","front":"Energy Pyramid","back":"shows how much energy is available to each successive trophic level","sourcePage":4},{"id":"apes-u12-c26","front":"Food Webs","back":"show the complex interactions between many species","sourcePage":4},{"id":"apes-u12-c27","front":"Ecosystem Diversity","back":"describes how variable an ecosystem is within a geographical location","sourcePage":4},{"id":"apes-u12-c28","front":"Biodiversity","back":"The number and variety of organisms found in the world or in a particular habitat or ecosystem The variability among living organisms Biodiversity in all forms is the result evolution More biodiversity means a larger and more diverse gene pool, which leads to a greater chance of adaptation and survival","sourcePage":4},{"id":"apes-u12-c29","front":"Evolution","back":"the change in the population’s genetic composition over time","sourcePage":4},{"id":"apes-u12-c30","front":"Natural Selection","back":"The natural selection of advantageous traits changes the makeup of a population","sourcePage":4},{"id":"apes-u12-c31","front":"Evolution by natural selection","back":"The process by which heritable traits that improve survival or reproduction become more common in a population across generations.","sourcePage":4},{"id":"apes-u12-c32","front":"Genetic Drift","back":"Chance events change the makeup of a population with no regard to traits","sourcePage":4},{"id":"apes-u12-c33","front":"Phylogenetic Tree","back":"a diagram that shows how organisms are related based on evolutionary relationships.","sourcePage":4},{"id":"apes-u12-c34","front":"Species","back":"a group of organisms that are capable of breeding with one another but incapable of breeding with other species","sourcePage":4},{"id":"apes-u12-c35","front":"Speciation","back":"the formation of new species from preexisting species","sourcePage":4},{"id":"apes-u12-c36","front":"Extinction","back":"occurs when a species cannot adapt quickly enough to environmental change and all members of the species die","sourcePage":4},{"id":"apes-u12-c37","front":"Biological Extinction","back":"The permanent loss of a species when its last surviving individual dies, leaving no living members anywhere on Earth.","sourcePage":4},{"id":"apes-u12-c38","front":"Ecological Extinction","back":"So few individuals of a species that this species can no longer perform its ecological function Eg: Alligators in the Everglades in 1960; Wolves in Yellowstone before reintroduction in the 1990s","sourcePage":5},{"id":"apes-u12-c39","front":"Commercial or Economic Extinction","back":"A few individuals exist, but the effort needed to locate and harvest them is not worth the expense Eg: Groundfish population of the Grand Banks","sourcePage":5},{"id":"apes-u12-c40","front":"Ecosystem Services","back":"Humans gain many benefits from the natural environment and from properly functioning ecosystems Ecosystems are essential to life Land, water, and air must be used responsibly if they are to benefit future generations","sourcePage":5},{"id":"apes-u12-c41","front":"Provisioning Services","back":"Physical items we obtain from our environment Example Food Raw materials Water Energy Medicinal resources","sourcePage":5},{"id":"apes-u12-c42","front":"Cultural Services","back":"Non-material benefits people obtain from the ecosystem Example Recreation Science & education Tourism Inspiration for culture & art Spiritual experience","sourcePage":5},{"id":"apes-u12-c43","front":"Regulating Services","back":"Benefits obtained from the regulating of ecosystems. These are ften hard to see and are taken for granted Example Pest & disease control Water & air purification Climate regulation Waste decomposition & detoxification Pollination","sourcePage":5},{"id":"apes-u12-c44","front":"Supporting ecosystem services","back":"Underlying ecological processes that make other ecosystem services possible, including nutrient cycling, soil formation, primary production, and habitat provision.","sourcePage":5},{"id":"apes-u12-c45","front":"Keystone species","back":"A species whose ecological impact is disproportionately large relative to its abundance; removing it can cause major changes throughout the community.","sourcePage":6},{"id":"apes-u12-c46","front":"Indicator species","back":"A species whose presence, absence, or condition provides information about environmental quality or ecosystem change.","sourcePage":6},{"id":"apes-u12-c47","front":"Primary Succession","back":"Begins in a virtually lifeless area, such as the area below a retreating glacier","sourcePage":6},{"id":"apes-u12-c48","front":"Secondary Succession","back":"Takes place where an existing community has been cleared, but the soil has been left intact","sourcePage":6},{"id":"apes-u12-c49","front":"Pioneer Species","back":"Organisms present in the first stages of either type of succession Have wide ranges of environmental tolerance","sourcePage":6},{"id":"apes-u12-c50","front":"Climax Community","back":"Formed in the final stage of succession Have a dynamic balance between abiotic and biotic components of the community","sourcePage":6},{"id":"apes-u12-c51","front":"Habitat Fragmentation","back":"When a natural habitat is reduced or fragmented When a regular and balanced ecosystem is damaged","sourcePage":6}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-12-f1","prompt":"Ecosystem structure"},{"id":"apes-unit-12-f2","prompt":"Species interactions"},{"id":"apes-unit-12-f3","prompt":"Energy flow through ecosystems"},{"id":"apes-unit-12-f4","prompt":"Biodiversity and ecosystem stability"},{"id":"apes-unit-12-f5","prompt":"Ecological succession"}]},{"id":"apes-unit-3","name":"AP Environmental Science - Unit 3","shortName":"Unit 3: Populations","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u3-c1","front":"Population","back":"A group of individuals of the same species living in the same area at the same time and capable of interacting and reproducing.","sourcePage":7},{"id":"apes-u3-c2","front":"Population Density","back":"the number of individuals of a population that inhabit a certain unit of land or water area","sourcePage":7},{"id":"apes-u3-c3","front":"Population Dispersion","back":"how individuals of a population are spaced within a region","sourcePage":7},{"id":"apes-u3-c4","front":"Clumped Dispersion","back":"The most common dispersion pattern for populations Adheres to the “those of a feather flock together” idea Eg: Plants & fish","sourcePage":7},{"id":"apes-u3-c5","front":"Uniform Dispersion","back":"Members of a population are uniformly spaced throughout their geographic region; usually a result of competition for an ecosystem’s resources Eg: Trees","sourcePage":7},{"id":"apes-u3-c6","front":"Random Dispersion","back":"A relatively uncommon pattern of dispersion Occurs when the position of each member of a population is not determined or influenced by other members of the population","sourcePage":7},{"id":"apes-u3-c7","front":"Biotic Potential","back":"How much a population would grow if there were unlimited resources in the environment Not a practical model for population growth because resources in an environment are limited","sourcePage":7},{"id":"apes-u3-c8","front":"Carrying Capacity","back":"The maximum population size that can be supported by the available resources in the region Differ by species, as different species have different requirements for life","sourcePage":7},{"id":"apes-u3-c9","front":"J-Curve Model","back":"A graph of exponential population growth in which population size rises increasingly rapidly when resources are effectively unlimited.","sourcePage":7},{"id":"apes-u3-c10","front":"Logistic Population Growth (S-Curve)","back":"Population growth that begins rapidly, slows as limiting factors intensify, and levels near the environment's carrying capacity.","sourcePage":7},{"id":"apes-u3-c11","front":"Rule of 70","back":"the time it takes for a population to double can be approximated by dividing 70 by the current growth rate of the population 70 Eg: = 2.8 years 25%","sourcePage":7},{"id":"apes-u3-c12","front":"R-selected Organisms","back":"Reproduces early in life Usually have a high capacity for reproductive growth Little to no care given to offspring Eg; Bacteria, algae, protozoa","sourcePage":7},{"id":"apes-u3-c13","front":"K-selected Organisms","back":"Reproduces later in life Produces fewer organisms Devote significant time and energy to nurturing of offspring Parents are invested in each individual offspring Eg: Humans, lions, cows","sourcePage":8},{"id":"apes-u3-c14","front":"Boom-and-Bust Cycle","back":"Very common among r-strategists Rapid increase→Equally rapid drop -off","sourcePage":8},{"id":"apes-u3-c15","front":"Density-dependent Factors","back":"Increased predation Competition for food or living space Disease Buildup of toxic materials","sourcePage":8},{"id":"apes-u3-c16","front":"Density-independent Factors","back":"Environmental events whose effects do not depend on population density, such as droughts, freezes, floods, fires, storms, and earthquakes.","sourcePage":8},{"id":"apes-u3-c17","front":"Type I survivorship curve","back":"A survivorship pattern with low mortality through early and middle life followed by high mortality in old age, typical of humans and other large mammals.","sourcePage":8},{"id":"apes-u3-c18","front":"Type II survivorship curve","back":"A survivorship pattern with a roughly constant probability of death at every age, seen in many birds and some rodents.","sourcePage":8},{"id":"apes-u3-c19","front":"Type III survivorship curve","back":"A survivorship pattern with very high juvenile mortality but relatively long survival among the few individuals that reach adulthood, common in fish, insects, and many plants.","sourcePage":8},{"id":"apes-u3-c20","front":"Birth rate","back":"the number of live births per 1,000 members of the population in a year","sourcePage":8},{"id":"apes-u3-c21","front":"Death rate","back":"the number of deaths per 1,000 members (𝐵𝑖𝑟𝑡ℎ 𝑟𝑎𝑡𝑒+𝑖𝑚𝑚𝑖𝑔𝑟𝑎𝑡𝑖𝑜𝑛)−(𝑑𝑒𝑎𝑡ℎ 𝑟𝑎𝑡𝑒+𝑒𝑚𝑖𝑔𝑟𝑎𝑡𝑖𝑜𝑛)","sourcePage":8},{"id":"apes-u3-c22","front":"Emigration","back":"The movement of individuals out of a population, which decreases that population's size.","sourcePage":8},{"id":"apes-u3-c23","front":"Immigration","back":"The movement of individuals into a population, which increases that population's size.","sourcePage":8},{"id":"apes-u3-c24","front":"Total Fertility Rate","back":"The number of children a woman in a given population will bear during her lifetime Based on an analysis of data from preceding years TFRs cannot be depended on because they assume the conditions f the past will be the conditions of the future","sourcePage":8},{"id":"apes-u3-c25","front":"Replacement Birth Rate","back":"The number of children a couple must have in order to replace themselves in a population Worldwide, the replacement birth rate is slightly higher than 2 In developing countries, this number is as high as 3.4 due to higher mortality rates","sourcePage":9},{"id":"apes-u3-c26","front":"Ecological Footprint","back":"Used to describe the environmental impact of a population","sourcePage":9},{"id":"apes-u3-c27","front":"IPAT equation","back":"A conceptual model stating that environmental impact equals population multiplied by affluence and technology: I = P × A × T.","sourcePage":9},{"id":"apes-u3-c28","front":"Green Revolution","back":"the technological innovation and an increased use of pesticides and fertilizers, which allowed farmer to increase crop production throughout the world","sourcePage":9},{"id":"apes-u3-c29","front":"Extensive Pastoralism","back":"the shifting of animal herds between grazing pastures has remained popular in several arid parts of the world","sourcePage":9},{"id":"apes-u3-c30","front":"Population Pressure","back":"too many people and too many animals on too little lands","sourcePage":9},{"id":"apes-u3-c31","front":"Overgrazing","back":"led to significant amounts of dry grassland being denuded, eroded, and desertified","sourcePage":9},{"id":"apes-u3-c32","front":"Desertification","back":"any human process that turns a vegetated environment into a desert-like landscape","sourcePage":9},{"id":"apes-u3-c33","front":"Soil Salinization","back":"the salt content in soil increasing due to non- anthropogenic and/or anthropogenic influences","sourcePage":9},{"id":"apes-u3-c34","front":"Irrigation","back":"the application of controlled amounts of water to plants at needed intervals","sourcePage":10},{"id":"apes-u3-c35","front":"Aquifers","back":"underground water tables Aquifer supplies are being depleted at a rapid rate in large scale countries such as India, China and the United States","sourcePage":10},{"id":"apes-u3-c36","front":"Deforestation","back":"the act of clearing a forested area of trees and ther vegetation without the intention of replanting","sourcePage":10},{"id":"apes-u3-c37","front":"Vulnerable Species","back":"The species is likely to become endangered if no action is taken","sourcePage":10},{"id":"apes-u3-c38","front":"Endangered Species","back":"A species at serious risk of extinction throughout all or a significant portion of its range.","sourcePage":10},{"id":"apes-u3-c39","front":"Critically Endangered","back":"The species is at a very high risk of extinction","sourcePage":10},{"id":"apes-u3-c40","front":"Background Extinction Rate","back":"Species that are the most endangered have several factors in common They Require large ranges of habitat to survive Have low reproductive rates Have specialized feeding habits Have some sort of value for humans Have low population numbers","sourcePage":10},{"id":"apes-u3-c41","front":"Fragmentation","back":"habitats are broken into smaller pieces by, for example, building of roads and cities","sourcePage":10},{"id":"apes-u3-c42","front":"Degradation","back":"The deterioration of habitat or environmental quality through pollution, resource depletion, fragmentation, erosion, or other disturbances.","sourcePage":10},{"id":"apes-u3-c43","front":"Overexploitation","back":"The unsustainable harvesting of organisms faster than their populations can replace themselves, increasing the risk of population collapse or extinction.","sourcePage":10},{"id":"apes-u3-c44","front":"HIPPCO","back":"an acronym to memorize the cause of extinction","sourcePage":10}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-3-f1","prompt":"Population growth and carrying capacity"},{"id":"apes-unit-3-f2","prompt":"R-selected vs. K-selected species"},{"id":"apes-unit-3-f3","prompt":"Human population growth"},{"id":"apes-unit-3-f4","prompt":"The IPAT model and ecological footprints"}]},{"id":"apes-unit-4","name":"AP Environmental Science - Unit 4","shortName":"Unit 4: Earth Systems and Resources","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u4-c1","front":"Tectonic Plates","back":"parts of the lithosphere that float on the asthenosphere Earth’s Tectonic Plates","sourcePage":11},{"id":"apes-u4-c2","front":"Plate Boundaries","back":"the edges of tectonic plates Types of Plate Boundaries","sourcePage":11},{"id":"apes-u4-c3","front":"Convergent Boundary","back":"two plates are pushed toward and into each other","sourcePage":11},{"id":"apes-u4-c4","front":"Divergent Boundary","back":"A plate boundary where tectonic plates move apart, allowing magma to rise and create new crust at features such as mid-ocean ridges and rift valleys.","sourcePage":11},{"id":"apes-u4-c5","front":"Transform Fault Boundary","back":"two plates slide against each ther in opposite directions","sourcePage":11},{"id":"apes-u4-c6","front":"Subduction","back":"an older and denser plate sinks beneath the younger and lighter plate","sourcePage":11},{"id":"apes-u4-c7","front":"Ocean-continent convergence","back":"the oceanic plate is subducted beneath the less dense continental plate, forming a deep ocean trench Eg: Cascade Range is an example of ocean-continent convergence","sourcePage":11},{"id":"apes-u4-c8","front":"Earthquakes","back":"geological events resulting from vibrations deep in the Earth that release energy","sourcePage":11},{"id":"apes-u4-c9","front":"Epicenter","back":"The point on Earth's surface directly above an earthquake's focus, where the rupture begins underground.","sourcePage":11},{"id":"apes-u4-c10","front":"Seismograph","back":"an instrument that measures size or magnitude","sourcePage":11},{"id":"apes-u4-c11","front":"Richter Scale","back":"A logarithmic scale historically used to express earthquake magnitude from the amplitude of seismic waves recorded by a seismograph.","sourcePage":11},{"id":"apes-u4-c12","front":"Volcanoes","back":"geological events resulting from plate movement","sourcePage":11},{"id":"apes-u4-c13","front":"Active volcano","back":"A volcano that is erupting, has erupted in recent geologic history, or shows signs that it may erupt again.","sourcePage":11},{"id":"apes-u4-c14","front":"Dormant volcano","back":"Has not erupted within the last 10,000 years but is expected to erupt again","sourcePage":11},{"id":"apes-u4-c15","front":"Extinct volcano","back":"A volcano that scientists do not expect to erupt again because it no longer has an active magma supply.","sourcePage":11},{"id":"apes-u4-c16","front":"Subduction Zone","back":"Occurs at convergent boundaries between ceanic and continental plates Eg: Ring of Fire","sourcePage":11},{"id":"apes-u4-c17","front":"Rift Valley","back":"Occurs at divergent boundaries usually between ceanic plates. New ocean floor is formed as magma fills in the gap between separating plates. Eg: East African Rift","sourcePage":11},{"id":"apes-u4-c18","front":"Hotspots","back":"Found in the middle of tectonic plates. Columns of unusually hot magma rise from deep in the mantle, partially melting and weakening the mantle in the lower lithosphere. Eg: Hawaiian Islands","sourcePage":11},{"id":"apes-u4-c19","front":"Shield Volcanoes","back":"Broad, gently sloping volcanoes formed by repeated eruptions of low-viscosity basaltic lava, such as Mauna Loa.","sourcePage":11},{"id":"apes-u4-c20","front":"Composite Volcanoes","back":"Tall, steep-sided volcanoes built from alternating layers of lava and pyroclastic material; they can produce explosive eruptions.","sourcePage":12},{"id":"apes-u4-c21","front":"Cinder Cones","back":"Small, Short, Steep slope, Symmetrical cone, Bowl-like crater, Eg: Sunset Crater","sourcePage":12},{"id":"apes-u4-c22","front":"Lava Domes","back":"Small, Short, Steep slope, Dome Eg: Mount St. Helens","sourcePage":12},{"id":"apes-u4-c23","front":"Exosphere","back":"The outermost atmospheric layer, where gases are extremely sparse and gradually merge with outer space.","sourcePage":12},{"id":"apes-u4-c24","front":"Thermosphere","back":"A very thin upper atmospheric layer above the mesosphere where absorption of high-energy solar radiation produces high temperatures and auroras occur.","sourcePage":12},{"id":"apes-u4-c25","front":"Ionosphere","back":"Absorbs X-rays and ultraviolet radiation from Sun","sourcePage":12},{"id":"apes-u4-c26","front":"Mesosphere","back":"Air pressure extremely low Temperature decreases with altitude Where meteors usually burn up before striking Earth","sourcePage":12},{"id":"apes-u4-c27","front":"Stratosphere","back":"Includes the ozone layer Gases are not well mixed Gradually warmer with altitude","sourcePage":12},{"id":"apes-u4-c28","front":"Tropopause","back":"The boundary between the troposphere and stratosphere, where the troposphere's general decrease in temperature with altitude stops.","sourcePage":12},{"id":"apes-u4-c29","front":"Troposphere","back":"Where weather takes place Usually well-mixed Gradually colder with altitude Contains 99% of water vapor and clouds","sourcePage":12},{"id":"apes-u4-c30","front":"Weather","back":"Day-to-Day properties Wind Speed + Directions Temperature Amount of Sunlight Pressure Humidity","sourcePage":12},{"id":"apes-u4-c31","front":"Climate","back":"Patterns that are constant over many years Average Temperature Average Precipitation Amounts","sourcePage":12},{"id":"apes-u4-c32","front":"Seasons","back":"the motion of the Earth around the Sun that results in a variation in insolation, the amount of solar radiation that reaches a given area Northern Hemisphere Tilted Towards the Sun North = Summer South = Winter Southern Hemisphere Tilted Towards the Sun North = Winter South = Summer","sourcePage":13},{"id":"apes-u4-c33","front":"The Hydrosphere","back":"Includes Earth’s oceans and freshwater bodies Covers about 75% of planet Earth","sourcePage":13},{"id":"apes-u4-c34","front":"Freshwater","back":"Contains minimal quantities of dissolved salts Usually comes from precipitation from atmospheric water vapor","sourcePage":13},{"id":"apes-u4-c35","front":"Watershed","back":"an area of land that collects rainwater and drains it into a particular stream or river","sourcePage":13},{"id":"apes-u4-c36","front":"Deltas","back":"Landforms that forms at the juncture of a river and ocean Made of deposited sediment","sourcePage":13},{"id":"apes-u4-c37","front":"Estuaries","back":"Sites where the “arm” of the sea extends inland to meet the mouth of a river Often rich with many different types of plant and animal species Water usually has a high concentration of nutrients and sediments","sourcePage":13},{"id":"apes-u4-c38","front":"Wetlands","back":"Ecologically diverse ecosystems Found along the shores of fresh bodies of water Eg: Marshes, swamps, bogs, prairie potholes, and floodplains","sourcePage":13},{"id":"apes-u4-c39","front":"Barrier Islands","back":"Landforms that lie off coastal shores Spits of land Created by buildup of deposited sediments Boundaries constantly shifting as water moves around them Function to buffer the shoreline behind them","sourcePage":14},{"id":"apes-u4-c40","front":"Coral Reef","back":"A type of barrier island Formed by a community of living things Home to a large diversity of species Extremely delicate Vulnerable to physical stresses, changes in light intensity, changes in water temperature, and ocean depth and pH","sourcePage":14},{"id":"apes-u4-c41","front":"Water Risk","back":"The possibility of an area experiencing a water-related challenge such as water scarcity, water stress, flooding or drought","sourcePage":14},{"id":"apes-u4-c42","front":"Water Stress","back":"Occurs when demand for water exceeds the available amount during a certain period, or when poor quality restricts water use. Water-stressed countries have a renewable annual water supply of about 1,000-2,000 m³ per person.","sourcePage":14},{"id":"apes-u4-c43","front":"Water Scarcity","back":"A lack of sufficient available water resources to meet demand for water in a region. It affects every continent and around 2.8 billion people around the world at least one month out of every year. Water-scarce countries have a renewable annual water supply of less than 1,000 m³ per person","sourcePage":14},{"id":"apes-u4-c44","front":"Water Conservation","back":"Includes Policies, strategies, and activities to sustainably manage the natural resource of fresh water, to protect the hydrosphere, and to meet the current and future human demand for water.","sourcePage":14},{"id":"apes-u4-c45","front":"Soil","back":"A mixture of weathered mineral particles, organic matter, water, air, and living organisms that supports terrestrial plant growth and nutrient cycling.","sourcePage":14},{"id":"apes-u4-c46","front":"The Chemistry of Soil: pH","back":"pH substances ranges from 0-14 pH is the measure of the concentration of hydrogen ions Most soils have a pH between 4 to 8 Soil can be acidic (<7) or alkaline/basic (>7)","sourcePage":14},{"id":"apes-u4-c47","front":"Igneous rock","back":"Rock formed when molten magma or lava cools and solidifies.","sourcePage":15},{"id":"apes-u4-c48","front":"Sedimentary rock","back":"Rock formed when sediments are deposited, compacted, and cemented or when minerals precipitate from water.","sourcePage":15},{"id":"apes-u4-c49","front":"Metamorphic rock","back":"Rock altered from an existing rock type by heat, pressure, or chemically active fluids without completely melting.","sourcePage":15},{"id":"apes-u4-c50","front":"Physical weathering","back":"Rock is weakened and worn down by physical forces, usually wind or water No change in the chemistry of the rock Dominates in cold or dry environments","sourcePage":15},{"id":"apes-u4-c51","front":"Chemical weathering","back":"Rock is subjected to chemical alteration through reactions with water, oxygen, or dissolved minerals Breakdown and reorganization of rock minerals Dominates in warm or moist environments","sourcePage":15},{"id":"apes-u4-c52","front":"Biological weathering","back":"Weathering that takes place as the result of the activities of living organisms Organisms can weather rock by physical or chemical means","sourcePage":16},{"id":"apes-u4-c53","front":"Sand","back":"Large particles Don’t easily adhere together Large pores More space for water but it drains away quickly","sourcePage":16},{"id":"apes-u4-c54","front":"Clay","back":"Small particles Easily adhere to each other Small pores Less space for water but is held in soil and doesn’t drain","sourcePage":16},{"id":"apes-u4-c55","front":"Erosion","back":"The removal of soil, rock, or dissolved material from one location n the Earth’s crust and transportation to another location","sourcePage":16},{"id":"apes-u4-c56","front":"Monoculture","back":"Planting just one type of crop in a large area Common in modern agriculture Leeches soil of specific nutrients Decreases crop genetic diversity, making crops more susceptible to pests and diseases","sourcePage":16},{"id":"apes-u4-c57","front":"Polyculture","back":"Planting many types of crops in a large area Increases sustainability Limits nutrient depletion in soil Increases genetic diversity Crop rotation another good solution","sourcePage":16}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-4-f1","prompt":"Plate tectonics and volcanism"},{"id":"apes-unit-4-f2","prompt":"Atmospheric structure and the greenhouse effect"},{"id":"apes-unit-4-f3","prompt":"Freshwater and marine systems"},{"id":"apes-unit-4-f4","prompt":"Soil formation and soil chemistry"},{"id":"apes-unit-4-f5","prompt":"The rock cycle and weathering"},{"id":"apes-unit-4-f6","prompt":"Agriculture and soil conservation"}]},{"id":"apes-unit-5","name":"AP Environmental Science - Unit 5","shortName":"Unit 5: Land and Water Use","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u5-c1","front":"“The Tragedy of the Commons”","back":"Serves as a foundation for modern conservation","sourcePage":18},{"id":"apes-u5-c2","front":"Conservation","back":"the management or regulation of a resource Different from preservation","sourcePage":18},{"id":"apes-u5-c3","front":"Preservation","back":"the maintenance of a species or ecosystem in order to ensure its perpetuation","sourcePage":18},{"id":"apes-u5-c4","front":"Renewable Resources","back":"Resources that can be regenerated quickly Eg: Hardwood trees take 50 years to mature; It’s widely considered the crossover point of nonrenewable and renewable resources.","sourcePage":18},{"id":"apes-u5-c5","front":"Nonrenewable Resource","back":"Things like minerals and fossil fuels Typically formed by very slow geologic processes","sourcePage":18},{"id":"apes-u5-c6","front":"Fossil Fuels","back":"Provide 65% of the world’s electricity Formed from the fossilized remains of once-living rganisms; over time, this organic matter was exposed to intense heat & pressure, eventually breaking the organic molecules down into oil, coal, and natural gas","sourcePage":18},{"id":"apes-u5-c7","front":"Nuclear Energy","back":"Energy stored in atomic nuclei and released through fission, fusion, or radioactive decay.","sourcePage":18},{"id":"apes-u5-c8","front":"Renewable Energy","back":"Energy from sources replenished naturally on a human time scale, including sunlight, wind, flowing water, biomass, and geothermal heat.","sourcePage":18},{"id":"apes-u5-c9","front":"Neolithic Agricultural Revolution","back":"the period of time during which people transitioned from hunting and gathering for food to an organized system of farming","sourcePage":19},{"id":"apes-u5-c10","front":"Vegetative planting","back":"where shoot, stems, and roots of existing wild plants are collected and grown together ↓","sourcePage":19},{"id":"apes-u5-c11","front":"Seed agriculture","back":"Cultivation in which farmers plant and reproduce crops using seeds rather than vegetative cuttings or root fragments.","sourcePage":19},{"id":"apes-u5-c12","front":"Horticulture","back":"the domestication of plants by rejecting poorly growing crops and taking seeds from productive, heartier crops to grow future generations ↓","sourcePage":19},{"id":"apes-u5-c13","front":"Animal domestication","back":"the process in which selected animal populations become accustomed to human provision and control; was established as an alternative to hunting & fishing ↓","sourcePage":19},{"id":"apes-u5-c14","front":"Animal husbandry","back":"productive breeds were purposely interbred r hybridized for reproduction","sourcePage":19},{"id":"apes-u5-c15","front":"Second Agricultural Revolution","back":"technological innovations in agriculture and manufacturing that drastically reduced labor requirements and increased the scale of farm production","sourcePage":19},{"id":"apes-u5-c16","front":"Green Revolution","back":"the time after the Industrial Revolution when farming became mechanized and crop yields in industrialized nations booms","sourcePage":19},{"id":"apes-u5-c17","front":"Intercropping","back":"Also called strip cropping The practice of planting bands of different crops across a hillside Can also prevent some erosion by creating an extensive network of roots","sourcePage":20},{"id":"apes-u5-c18","front":"Contour Plowing","back":"Rows of crops are plowed across the hillside; prevents the erosion that can occur when rows are cut up and down on a slope","sourcePage":20},{"id":"apes-u5-c19","front":"Terracing","back":"Aids in preventing in soil erosion on steep slopes Terraces are flat platforms that are cut into the hillside to provide a level planting surface; this reduces the soil runoff from the slope","sourcePage":20},{"id":"apes-u5-c20","front":"No-till farming","back":"Planting crops directly into the residue of previous crops without plowing, which reduces erosion, soil disturbance, fuel use, and carbon loss.","sourcePage":20},{"id":"apes-u5-c21","front":"Crop Rotation","back":"Can provide soils with nutrients when legumes are part of the cycle f crops in an area","sourcePage":20},{"id":"apes-u5-c22","front":"Biological pest control","back":"The use of predators, parasites, pathogens, or competitors to reduce pest populations instead of relying only on chemical pesticides.","sourcePage":20},{"id":"apes-u5-c23","front":"Carbamates","back":"A class of pesticides that disrupts nervous-system function by inhibiting acetylcholinesterase; many break down faster than organochlorines but can still harm nontarget organisms.","sourcePage":20},{"id":"apes-u5-c24","front":"Persistent organic pollutants (POPs)","back":"Carbon-based chemicals that resist degradation, travel long distances, bioaccumulate in organisms, and biomagnify through food webs; examples include DDT and PCBs.","sourcePage":20},{"id":"apes-u5-c25","front":"Fumigants","back":"Used to sterilize soil and prevent pest infestation of stored grain","sourcePage":21},{"id":"apes-u5-c26","front":"Inorganic pesticides","back":"Pesticides made from toxic elements or mineral compounds, such as compounds containing arsenic, copper, lead, or mercury, that can persist in the environment.","sourcePage":21},{"id":"apes-u5-c27","front":"Botanical pesticides","back":"Pesticides derived from plants, such as pyrethrins from chrysanthemums or nicotine from tobacco; natural origin does not necessarily mean nontoxic.","sourcePage":21},{"id":"apes-u5-c28","front":"Organophosphates","back":"Extremely toxic but remain in the environment for only a brief time Eg: Malathium","sourcePage":21},{"id":"apes-u5-c29","front":"Livestock Grazing","back":"The shifting of animal herds between grazing pastures in area where dry grassland is common A sustainable practice, as long as the grazing area is sufficient for the number of animals","sourcePage":21},{"id":"apes-u5-c30","front":"Overgrazing","back":"Occurs when too many people and too many animals are placing population pressure on too little land Has led to significant amounts to dry grasslands being denuded, eroded, and desertified Harmful to the soil because it leads to erosion and soil compaction Solutions include rotating animals from site to site and away from their source of water, and overall control of herd numbers","sourcePage":21},{"id":"apes-u5-c31","front":"Animal Waste","back":"Manure not used as fertilizer due to difficulty with transport Has become the most widespread source of water pollution in the United States","sourcePage":21},{"id":"apes-u5-c32","front":"Deforestation","back":"The removal of trees for agricultural purposes or purposes of exportation","sourcePage":21},{"id":"apes-u5-c33","front":"Slash-and-burn agriculture","back":"A form of shifting cultivation in which vegetation is cut and burned to clear land and release nutrients before short-term cropping.","sourcePage":21},{"id":"apes-u5-c34","front":"Old Growth Forests","back":"Have never been cut or seriously disturbed for several hundred years Contains incredible biodiversity, with nyriad habitats and highly evolved intricate niches for a multitude of organisms","sourcePage":21},{"id":"apes-u5-c35","front":"Second Growth Forests","back":"Areas where cutting has occurred and a new, younger forest has arisen naturally","sourcePage":22},{"id":"apes-u5-c36","front":"Plantations & Tree Farms","back":"Planted and managed tracts of trees of the same age that are harvested for commercial use","sourcePage":22},{"id":"apes-u5-c37","front":"Silviculture","back":"the management of forest plantations for the purpose f harvesting timber","sourcePage":22},{"id":"apes-u5-c38","front":"Clear-Cutting","back":"A timber-harvesting method that removes nearly all trees from an area at once, efficiently producing wood but increasing erosion, runoff, habitat loss, and stream warming.","sourcePage":22},{"id":"apes-u5-c39","front":"Selective Cutting","back":"A timber-harvesting method that removes selected trees while leaving most of the forest standing, generally reducing disturbance compared with clear-cutting.","sourcePage":22},{"id":"apes-u5-c40","front":"Rangelands","back":"Are diverse in nature, consisting of desert, wet and dry grasslands, and mountainous meadows Approximately 770 million acres are rangelands; 46% of it is governed","sourcePage":22},{"id":"apes-u5-c41","front":"Strip Mining","back":"Controversial type of mining Strips the surface layer of soil and rock in order to expose a seam of mineral ore Least expensive and least dangerous method of mining for coal Has a detrimental effect on the environment","sourcePage":22},{"id":"apes-u5-c42","front":"Mountaintop Removal","back":"Most extreme form of strip mining Mostly associated with coal mining in the Appalachian Mountains Transforms the summits of mountains and destroys ecosystems","sourcePage":22},{"id":"apes-u5-c43","front":"Shaft Mining","back":"Vertical tunnels are built to access Excavate minerals that are unreachable","sourcePage":22},{"id":"apes-u5-c44","front":"Drift Nets","back":"Nets float through the water and catch everything in their path","sourcePage":22},{"id":"apes-u5-c45","front":"Long-Lining","back":"The use of long lines with baited hooks that are taken by numerous aquatic organisms","sourcePage":22},{"id":"apes-u5-c46","front":"Bottom Trawling","back":"The ocean floor is scraped by heavy nets that smash everything in their path","sourcePage":23},{"id":"apes-u5-c47","front":"Overfishing","back":"Harvesting fish faster than populations can reproduce, causing declining stocks, altered food webs, and possible fishery collapse.","sourcePage":23},{"id":"apes-u5-c48","front":"Aquaculture","back":"raising aquatic species in captivity for harvesting","sourcePage":23}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-5-f1","prompt":"The tragedy of the commons"},{"id":"apes-unit-5-f2","prompt":"Renewable vs. nonrenewable resources"},{"id":"apes-unit-5-f3","prompt":"Agriculture and soil degradation"},{"id":"apes-unit-5-f4","prompt":"Forest and mineral resource management"},{"id":"apes-unit-5-f5","prompt":"Commercial fishing and aquaculture"}]},{"id":"apes-unit-6","name":"AP Environmental Science - Unit 6","shortName":"Unit 6: Energy Resources and Consumption","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u6-c1","front":"Potential energy","back":"Stored energy associated with an object's position, condition, or chemical composition that can be converted into other forms.","sourcePage":24},{"id":"apes-u6-c2","front":"Kinetic energy","back":"The energy of motion; an object's kinetic energy increases with its mass and the square of its speed.","sourcePage":24},{"id":"apes-u6-c3","front":"Radiant energy","back":"Energy carried by electromagnetic waves, including visible sunlight, infrared radiation, ultraviolet radiation, and radio waves.","sourcePage":24},{"id":"apes-u6-c4","front":"Thermal energy","back":"The internal energy associated with the random motion of particles in matter and transferred between objects as heat.","sourcePage":24},{"id":"apes-u6-c5","front":"Chemical energy","back":"energy stored in chemical bonds between atoms","sourcePage":24},{"id":"apes-u6-c6","front":"Electrical energy","back":"Energy associated with moving electric charges, commonly electrons traveling through a conductor.","sourcePage":24},{"id":"apes-u6-c7","front":"Nuclear energy","back":"Energy stored in atomic nuclei and released through fission, fusion, or radioactive decay.","sourcePage":24},{"id":"apes-u6-c8","front":"First Law of Thermodynamics","back":"Energy can neither be created nor destroyed It can only be transferred and transformed Eg: Photosynthesis","sourcePage":24},{"id":"apes-u6-c9","front":"Second Law of Thermodynamics","back":"Entropy (disorder) of the universe is increasing In most energy transformations, a significant fraction of energy is lost to the universe as heat Eg: Food chains","sourcePage":24},{"id":"apes-u6-c10","front":"Nonrenewable energy","back":"Energy from resources that form too slowly to be replenished on a human time scale, including coal, oil, natural gas, and uranium.","sourcePage":24},{"id":"apes-u6-c11","front":"Renewable energy","back":"Energy from sources replenished naturally on a human time scale, including sunlight, wind, flowing water, biomass, and geothermal heat.","sourcePage":24},{"id":"apes-u6-c12","front":"Oil","back":"A liquid fossil fuel composed mainly of hydrocarbons, formed from ancient organic matter and refined into fuels and petrochemical products.","sourcePage":24},{"id":"apes-u6-c13","front":"Coal","back":"Mixture of carbon, hydrogen, oxygen, and other atoms Types of Coals Anthracite = Purest Form Bituminous Subbituminous Lignite = Least Pure","sourcePage":24},{"id":"apes-u6-c14","front":"Natural Gas","back":"Mostly methane gas (CH ) with a mixture of other gases such as 4 Pentane (C H ) and Butane (C H ) 5 12 4 10","sourcePage":25},{"id":"apes-u6-c15","front":"Crude Oil","back":"Raw or fresh oil when it is pumped up from a reserve","sourcePage":25},{"id":"apes-u6-c16","front":"Methods of Extracting Oil","back":"Primary recovery uses natural reservoir pressure and pumping; secondary recovery injects water or gas to displace oil; enhanced recovery uses steam, heat, or chemicals to reduce viscosity and mobilize remaining oil.","sourcePage":25},{"id":"apes-u6-c17","front":"Coal mining","back":"occurs through two processes Strip Mining Removal of the Earth’s surface, all the way down to the level of coal seam Removed earth is called the overburden Coal is removed; overburden is replaced with and topped with soil Area contoured and re-vegetated Underground Mining Sink shafts to reach underground deposits Networks of tunnels are dug or blasted Humans enter these tunnels to manually retrieve coal","sourcePage":25},{"id":"apes-u6-c18","front":"Burning Coal","back":"Burning coal produces Air pollutants such as CO , NO , Hg, and SO 2 x 2 Fly ash - small dark flecks that are carried into the air Boiler residue - solid waste left at the bottom of the boiler","sourcePage":27},{"id":"apes-u6-c19","front":"Fusion","back":"Combining two small atoms to produce heavier atoms and energy Can release more energy than fission without producing as many radioactive by-products Reactions occur in the Sun Practice is still being developed","sourcePage":27},{"id":"apes-u6-c20","front":"Fission","back":"Discovered first Energetic splitting of large atoms into two smaller atoms To split an atom, you have to hit in with a neutron Several neutrons are released, which continue the chain reaction Used by all commercial nuclear power plants","sourcePage":27},{"id":"apes-u6-c21","front":"Nuclear Reactors","back":"Steam is piped directly to the turbines Steam spins turbines to generate electricity Water is cooled back into a liquid then pumped back to the core to be turned into steam again","sourcePage":27},{"id":"apes-u6-c22","front":"Hydroelectric power","back":"Electricity generated as moving water turns a turbine. It produces no chemical pollutants, but can cause thermal pollution and alter river flow and habitat.","sourcePage":null},{"id":"apes-u6-c23","front":"Solar power","back":"Solar panels convert solar energy into heat or electricity. Operation produces no pollutants and requires little maintenance, but manufacturing and storage have costs and output depends on sunlight.","sourcePage":null},{"id":"apes-u6-c24","front":"Biomass energy","back":"Energy from wood, charcoal, animal waste, or other biological material. It can be widely available and approximately carbon neutral, but may be expensive and contribute to deforestation.","sourcePage":null},{"id":"apes-u6-c25","front":"Wind power","back":"Wind rotates turbine blades to generate electricity. It produces no operational pollutants, but is intermittent and can create noise, visual, and siting concerns.","sourcePage":null},{"id":"apes-u6-c26","front":"Geothermal power","back":"Energy obtained from Earth's internal heat. It is reliable and produces little operational pollution, but is location-limited and can release dissolved gases or chemicals.","sourcePage":null},{"id":"apes-u6-c27","front":"Tidal energy","back":"Incoming or outgoing tides turn turbines to generate electricity. Tides are predictable, but suitable sites are limited and ecosystem effects remain a concern.","sourcePage":null},{"id":"apes-u6-c28","front":"Hydrogen fuel cell","back":"A device that uses hydrogen obtained from water or organic matter to generate electricity. Use is clean, but producing hydrogen can be expensive and may release pollutants.","sourcePage":null}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-6-f1","prompt":"Energy and the laws of thermodynamics"},{"id":"apes-unit-6-f2","prompt":"Fossil fuels and nuclear energy"},{"id":"apes-unit-6-f3","prompt":"Renewable energy systems and tradeoffs"}]},{"id":"apes-unit-78","name":"AP Environmental Science - Unit 7-8","shortName":"Unit 7-8: Atmospheric, Terrestrial, and Aquatic Pollution","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u78-c1","front":"Agricultural water use","back":"Freshwater used for irrigation and livestock; agriculture is the largest global human use of freshwater.","sourcePage":30},{"id":"apes-u78-c2","front":"Irrigation","back":"technological advances have made water use for crops more efficient. Furrow - a trench that is flooded with water Flood - the entire field is flooded with water Spray - an apparatus sprays water across the field Drip - a slow dripping hose is laid on or buried beneath the soil","sourcePage":30},{"id":"apes-u78-c3","front":"Hydroponic Agriculture","back":"Growing plants without soil by supplying roots with a controlled, nutrient-rich water solution; it can greatly reduce water and pesticide use but requires energy, equipment, and careful management.","sourcePage":30},{"id":"apes-u78-c4","front":"Industrial water use","back":"Freshwater used for manufacturing, processing, washing, cooling, and electricity generation.","sourcePage":30},{"id":"apes-u78-c5","front":"Residential water use","back":"Household water used for drinking, cooking, sanitation, cleaning, landscaping, and recreation.","sourcePage":31},{"id":"apes-u78-c6","front":"Oxygen depletion in water","back":"A decline in dissolved oxygen when microorganisms consume oxygen while decomposing organic matter, potentially creating hypoxic or anoxic conditions.","sourcePage":31},{"id":"apes-u78-c7","front":"Nutrient pollution","back":"Excess nitrogen or phosphorus entering water, often from fertilizer, sewage, or animal waste, and stimulating algal growth and eutrophication.","sourcePage":31},{"id":"apes-u78-c8","front":"Waterborne pathogens","back":"Disease-causing bacteria, viruses, protozoa, or parasites transmitted through contaminated water.","sourcePage":31},{"id":"apes-u78-c9","front":"Indicator species","back":"A species whose presence, absence, or condition provides information about environmental quality or ecosystem change.","sourcePage":31},{"id":"apes-u78-c10","front":"Fecal coliform bacteria","back":"a group of generally harmless microorganisms in human intestines that can serve as an indicator species for potentially harmful microorganisms associated w. contaminated sewage.","sourcePage":31},{"id":"apes-u78-c11","front":"Septic Systems","back":"Septic systems Septic tank Sludge Septage Leach field","sourcePage":31},{"id":"apes-u78-c12","front":"Sewage Treatment Plants","back":"In developed countries, municipalities use centralized sewage treatment plant that receive wastewater from hundreds or even thousands of households In traditional waste treatment plants, there are two phases of treatment; primary and secondary","sourcePage":32},{"id":"apes-u78-c13","front":"Animal Feedlots and Manure Lagoons","back":"Manure from concentrated animal feeding operations is a problem because of volume. It can also contain hormones and antibiotics that are given to the animals Manure lagoons - human-made ponds lined with rubber built to handle large quantities of manure produced by livestock. After the manure is broken down by bacteria\\, it is spread onto fields as fertilizers","sourcePage":32},{"id":"apes-u78-c14","front":"Lead","back":"found in pipes and other materials in older construction","sourcePage":32},{"id":"apes-u78-c15","front":"Arsenic","back":"occurs naturally and through human activity such as mining and industry","sourcePage":32},{"id":"apes-u78-c16","front":"Mercury","back":"occurs naturally and through human activity; primarily burning coal","sourcePage":32},{"id":"apes-u78-c17","front":"Acid deposition","back":"Acidic compounds deposited from the atmosphere as rain, snow, fog, gases, or particles, largely after sulfur dioxide and nitrogen oxides form acids.","sourcePage":32},{"id":"apes-u78-c18","front":"Synthetic organic water pollutants","back":"Human-made carbon-based chemicals such as solvents, pesticides, fuels, and industrial compounds that contaminate surface water or groundwater.","sourcePage":32},{"id":"apes-u78-c19","front":"Perchlorate contamination","back":"Water or soil contamination by perchlorate salts used in rocket fuel and explosives; exposure can interfere with thyroid function.","sourcePage":32},{"id":"apes-u78-c20","front":"Polychlorinated biphenyls (PCBs)","back":"Persistent industrial chemicals formerly used in electrical equipment that bioaccumulate, biomagnify, and can damage human and ecosystem health.","sourcePage":32},{"id":"apes-u78-c21","front":"Oil Pollution","back":"Petroleum products are highly toxic to many marine organisms, including birds, mammals and fish, as well as to the algae and microorganisms that form the base f the aquatic food chain One source of oil in the water comes from drilling from undersea oil using ffshore platforms Oil and other petroleum products can also enter the oceans as spills from oil tankers","sourcePage":33},{"id":"apes-u78-c22","front":"Solid Waste","back":"Garbage + Sludge produced by sewage treatment plants Garbage on beaches and in the ocean is dangerous to both marine rganisms and people In the United States the practice of dumping garbage in the ocean was curtailed in the early 1980s The problem remains in many developing countries.","sourcePage":33},{"id":"apes-u78-c23","front":"Sediment Pollution","back":"30% of all sediments in our waterways come from natural sources while 70% comes from human activities Problems with sedimentation Suspension of soil particles cause waterways to become brown and cloudy Reduced infiltration of sunlight lowers productivity of aquatic plants and algae Sediments clog gills and prevent aquatic organisms from obtaining oxygen","sourcePage":33},{"id":"apes-u78-c24","front":"Thermal Pollution","back":"non-chemical water pollution that occurs when human activities cause a substantial change in the temperature of water","sourcePage":33},{"id":"apes-u78-c25","front":"Thermal Shock","back":"a dramatic change in water temperature that can kill rganisms One common solution is cooling towers that release the excess heat into the atmosphere instead of into the water.","sourcePage":33},{"id":"apes-u78-c26","front":"Noise Pollution","back":"Sounds emitted by ships and submarines can interfere with animal communication Especially loud sonar can negatively affect species such as whales that rely on low-frequency, long distance communication. An increased awareness of noise pollution in the ocean has inspired some shipbuilders to design ships equipped with quieter propellers Developed countries have addressed the problems of pollution by clearing up polluted areas and by passing legislation to prevent pollution in the future. Developing countries are still in the process of industrializing and are less able to afford water-quality improvements Developing countries suffer from the additional pollution but also benefit economically from the additional.","sourcePage":33},{"id":"apes-u78-c27","front":"Air Pollution","back":"the introduction of chemicals, particulate matter, or microorganisms into the atmosphere at concentrations high enough to harm plants, animals, and materials such as buildings, or to alter an ecosystem Has many inputs and outputs","sourcePage":34},{"id":"apes-u78-c28","front":"Primary pollutant","back":"A pollutant emitted directly from a source, such as carbon monoxide, sulfur dioxide, nitrogen oxides, particulate matter, or volatile organic compounds.","sourcePage":34},{"id":"apes-u78-c29","front":"Secondary pollutant","back":"A pollutant formed in the atmosphere through chemical reactions involving primary pollutants, sunlight, water, or oxygen; examples include tropospheric ozone and acids.","sourcePage":34},{"id":"apes-u78-c30","front":"Sulfur Dioxide (SO2)","back":"A corrosive gas that comes primarily from combustion of fuels such as coal and oil A respiratory irritant and can adversely affect plant tissue Releases in large quantities during volcanic eruptions and in much similar quantities during forest fires.","sourcePage":34},{"id":"apes-u78-c31","front":"Nitrogen Oxides (NOx)","back":"Motor vehicles and stationary fossil fuel combustion are the primary anthropogenic sources of nitrogen oxides Respiratory irritant, increases susceptibility to respiratory infections An ozone precursor, leads to formation of photochemical smog Converts to nitric acid in atmosphere which is harmful to aquatic life and some vegetation Contributes to over-fertilizing terrestrial and aquatic systems","sourcePage":34},{"id":"apes-u78-c32","front":"Carbon Oxides","back":"Carbon monoxide (CO) is a common emission in vehicle exhaust and most other combustion processes CO can be a significant component of air pollution in urban areas Carbon dioxide (CO2) released by burning fossil fuels has led to its becoming a major pollutant CO2 recently exceeded a concentration of 400 parts per million in the atmosphere and appears to be steadily increasing each year.","sourcePage":34},{"id":"apes-u78-c33","front":"Particulate Matter","back":"Solid particles and liquid droplets suspended in air; fine particles can enter deep into the lungs and increase respiratory and cardiovascular risk.","sourcePage":35},{"id":"apes-u78-c34","front":"Haze","back":"Reduced atmospheric visibility caused by fine particles and droplets that scatter and absorb light; common sources include smoke, sulfates, nitrates, dust, and organic aerosols.","sourcePage":35},{"id":"apes-u78-c35","front":"Photochemical oxidant","back":"A class of air pollutants formed as a result of sunlight acting as compounds such as nitrogen oxides","sourcePage":35},{"id":"apes-u78-c36","front":"Ozone","back":"A secondary pollutant made up of three oxygen atoms bound together","sourcePage":35},{"id":"apes-u78-c37","front":"Smog","back":"A type of air pollution that is a mixture of oxidants and particulate matter","sourcePage":35},{"id":"apes-u78-c38","front":"Photochemical Smog","back":"A brownish mixture of secondary pollutants, especially tropospheric ozone, formed when nitrogen oxides and volatile organic compounds react in sunlight.","sourcePage":35},{"id":"apes-u78-c39","front":"Sulfurous smog","back":"Smog dominated by sulfur dioxide and sulfate compounds","sourcePage":35},{"id":"apes-u78-c40","front":"Volatile organic compound","back":"A carbon-containing compound that readily evaporates and can react with nitrogen oxides in sunlight to form photochemical smog and ozone.","sourcePage":35},{"id":"apes-u78-c41","front":"Air pollution control strategies","back":"Measures that prevent or reduce emissions, including cleaner fuels, catalytic converters, scrubbers, electrostatic precipitators, vapor recovery, efficiency standards, and public transit.","sourcePage":36},{"id":"apes-u78-c42","front":"Stratospheric ozone depletion","back":"The thinning of the protective ozone layer when chlorine or bromine radicals from compounds such as CFCs catalytically destroy stratospheric ozone.","sourcePage":36},{"id":"apes-u78-c43","front":"Water footprint","back":"The total daily per-capita use of freshwater.","sourcePage":null},{"id":"apes-u78-c44","front":"Biochemical oxygen demand","back":"The amount of oxygen a quantity of water uses over a period of time at a specified temperature.","sourcePage":null},{"id":"apes-u78-c45","front":"Dead zone","back":"An area with extremely low oxygen concentration and very little aquatic life.","sourcePage":null},{"id":"apes-u78-c46","front":"Eutrophication","back":"A process in which a body of water becomes rich in nutrients, often promoting algal growth and subsequent oxygen depletion.","sourcePage":null}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-78-f1","prompt":"Human water use and wastewater treatment"},{"id":"apes-unit-78-f2","prompt":"Eutrophication and oxygen depletion"},{"id":"apes-unit-78-f3","prompt":"Persistent, thermal, and sediment pollution"},{"id":"apes-unit-78-f4","prompt":"Air pollution and emission controls"},{"id":"apes-unit-78-f5","prompt":"Stratospheric ozone depletion"}]},{"id":"apes-unit-9","name":"AP Environmental Science - Unit 9","shortName":"Unit 9: Global Change","builtIn":true,"sourceTitle":"AP Environmental Science Study Guide - Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/60a02be2f3b25f044ccddca1_SS-AP-Env-Sci.pdf","cards":[{"id":"apes-u9-c1","front":"Changes in greenhouse gas concentrations","back":"Carbon Dioxide, CO 280 ppm 400 ppm 2 Methane, CH 715 ppb 1,840 ppb 4 Nitrous Oxides, N O 270 ppb 328 ppb 2","sourcePage":37},{"id":"apes-u9-c2","front":"Physical effects of climate change","back":"Decrease of glaciers and ice sheets Continued rising of average ocean levels Changes in precipitation Increase in frequency and duration of storms Increase in number of hot days Decrease in number of cold days","sourcePage":37},{"id":"apes-u9-c3","front":"Biological effects of climate change","back":"Increased crop yields in cold environments Loss of croplands due to drought and higher temperatures Cold-tolerant species will need to migrate to cooler climates Heat-tolerant species may spread and invade new habitats Additional deaths from water and insect-borne diseases Commerce, transport, and coastal settlements may be disrupted by changes in ocean levels and storms Change in marine ecosystems and fishery productivity","sourcePage":37},{"id":"apes-u9-c4","front":"Climate adaptation","back":"Must occur at many levels of society Develop new technology Continue to reduce emissions from engines Legislative and behavioral changes needed Promote sustainable growth","sourcePage":37},{"id":"apes-u9-c5","front":"Technological climate solutions","back":"Carbon sequestration Reduction of emissions from engines","sourcePage":37},{"id":"apes-u9-c6","front":"Behavioral climate solutions","back":"Turning off the lights to conserve electricity","sourcePage":37},{"id":"apes-u9-c7","front":"Climate policy solutions","back":"Government actions such as emissions standards, carbon pricing, clean-energy incentives, efficiency requirements, conservation programs, and international agreements that reduce greenhouse gas emissions or protect carbon sinks.","sourcePage":37},{"id":"apes-u9-c8","front":"Global warming","back":"The long-term rise in Earth's average temperature associated with increasing atmospheric greenhouse gas concentrations.","sourcePage":null},{"id":"apes-u9-c9","front":"Greenhouse effect","back":"The warming that occurs when greenhouse gases absorb and re-emit outgoing infrared radiation in the atmosphere.","sourcePage":null},{"id":"apes-u9-c10","front":"Carbon dioxide concentration","back":"The guide reports atmospheric carbon dioxide rising from about 280 ppm before industrialization to about 400 ppm in 2016.","sourcePage":null},{"id":"apes-u9-c11","front":"Methane concentration","back":"The guide reports atmospheric methane rising from about 715 ppb before industrialization to about 1,840 ppb in 2016.","sourcePage":null},{"id":"apes-u9-c12","front":"Nitrous oxide concentration","back":"The guide reports atmospheric nitrous oxide rising from about 270 ppb before industrialization to about 328 ppb in 2016.","sourcePage":null},{"id":"apes-u9-c13","front":"Carbon sequestration","back":"The capture and long-term storage of carbon as a technological approach to reducing climate change.","sourcePage":null},{"id":"apes-u9-c14","front":"Climate mitigation","back":"Actions that limit climate change by reducing greenhouse gas emissions or increasing carbon storage.","sourcePage":null}],"questions":[],"feynmanPrompts":[{"id":"apes-unit-9-f1","prompt":"Physical and biological effects of climate change"},{"id":"apes-unit-9-f2","prompt":"Climate mitigation and adaptation"}]}];
